582	### (i) Temporal workflow: `src/temporal/workflows.ts` (FROZEN at `real-run-start`)
583	
584	```ts
585	import * as wf from '@temporalio/workflow';
586	import type * as acts from './activities';
587	import type { Option } from '../shared/schema';
588	// Calls that cross the internet to Render/Gemma: fail fast (25 s fetch timeout inside), retry patiently.
589	const remote = wf.proxyActivities<typeof acts>({ startToCloseTimeout: '60 seconds',
590	  retry: { initialInterval: '5 seconds', backoffCoefficient: 2, maximumInterval: '2 minutes',
591	           maximumAttempts: 12, nonRetryableErrorTypes: ['BadRequest'] } });
592	const chat = wf.proxyActivities<typeof acts>({ startToCloseTimeout: '20 seconds', retry: { maximumAttempts: 6 } });
593	export const vote  = wf.defineSignal<[{ userId: string; name: string; optionIds: number[] }]>('vote');
594	export const recap = wf.defineSignal<[{ userId: string; name: string; line: string; photoFileId?: string }]>('recap');
595	export const phaseQuery = wf.defineQuery<string>('phase');
596	export interface PlanInput { planId: string; chatId: string; date: string; quorum: number;
597	  pollCloseAt: number; weatherCheckAt: number; reminderAt: number; outingEndAt: number }
598	const until = (t: number) => Math.max(1_000, t - Date.now());  // workflow Date.now() is deterministic
599	```
