625	  await wf.sleep(until(p.weatherCheckAt));                               // hours: the poll closes → 05:30
626	  const wx = await remote.recheckWeather(p, plan, options.filter((_, i) => i !== t.index)); // Render asleep → retries
627	  if (!wx.go && wx.fallback) { plan = wx.fallback; phase = 'fallback'; }
628	  await wf.sleep(until(p.reminderAt));                                   // 06:00 local
