685	```ts
686	const TG = `https://api.telegram.org/bot${process.env.TELEGRAM_BOT_TOKEN}`;
687	async function tg(method: string, body: object) {
688	  const r = await fetch(`${TG}/${method}`, { method: 'POST', headers: { 'content-type': 'application/json' },
689	    body: JSON.stringify(body), signal: AbortSignal.timeout(15_000) });
690	  const j = await r.json(); if (!j.ok) throw new Error(`${method}: ${j.description}`); return j.result;
691	}
692	export async function sendPoll(planId: string, chatId: string, options: Option[]) {
693	  const m = await tg('sendPoll', { chat_id: chatId, question: 'Which one are we actually doing? (tap all you can make)',
694	    options: [...options.map((o) => ({ text: o.title })), { text: "Can't make it" }],
695	    is_anonymous: false, allows_multiple_answers: true });             // non-anonymous → poll_answer updates
696	  await (await db()).collection<any>('polls').insertOne({ _id: m.poll.id, planId, chatId, messageId: m.message_id });
697	}
698	export async function closePoll(planId: string) {
699	  const poll = await (await db()).collection<any>('polls').findOne({ planId });
700	  if (poll) await tg('stopPoll', { chat_id: poll.chatId, message_id: poll.messageId }).catch(() => undefined);
701	}
702	// announce(p, kind, data): build the message per kind ('locked' includes `${PUBLIC_URL}/p/${p.planId}`),
703	// tg('sendMessage', …), then $set plans.status = kind. Keep wording human and short.
