### (a) Model switch: `src/shared/model.ts`

```ts
import { createOllama } from 'ollama-ai-provider-v2';
// QUORUM_MODEL = 'google/gemma-4-31b-it' (Gemini API free tier, default)
//              | 'google/gemma-4-26b-a4b-it' | 'ollama:gemma4:e4b' (local, private)
export function quorumModel() {
  const m = process.env.QUORUM_MODEL ?? 'google/gemma-4-31b-it';
  if (!m.startsWith('ollama:')) return m;          // Mastra model router string
  const ollama = createOllama({ baseURL: process.env.OLLAMA_BASE_URL ?? 'http://localhost:11434/api' });
  return ollama(m.slice('ollama:'.length)) as any; // AI SDK model object
}
```

### (b) Schemas: `src/shared/schema.ts`

```ts
import { z } from 'zod';
export const PlanOption = z.object({
  title: z.string().max(90),                 // must fit a Telegram poll option
  where: z.string().describe('exact name returned by the places tool'),
  start: z.string().describe('HH:MM local'),
  durationH: z.number().min(1).max(4),
  shapedBy: z.array(z.string()).describe('roster constraints that changed this option'),
  weatherNote: z.string(),
});
export const PlanOptions = z.object({ options: z.array(PlanOption).min(2).max(3) });
export type Option = z.infer<typeof PlanOption>;
export type RosterLine = { name: string; constraints: string[] };
```

### (c) Atlas client (one per process): `src/shared/db.ts`

```ts
import { MongoClient, type Db } from 'mongodb';
let client: MongoClient | undefined;
export async function db(): Promise<Db> {
  client ??= new MongoClient(process.env.MONGODB_URI!, { maxPoolSize: 5 }); // M0: 500 conns max
  await client.connect();                                                   // no-op if connected
  return client.db(process.env.MONGODB_DB ?? 'quorum');
}
export async function roster(chatId: string) {
  const ms = await (await db()).collection('members').find({ chatId }).toArray();
  return ms.map((m) => ({ name: m.name as string, constraints: (m.constraints ?? []).map((c: any) => c.text) }));
}
```

### (d) Tools: `src/mastra/tools/weather.ts` and `places.ts`

```ts
import { createTool } from '@mastra/core/tools';
import { z } from 'zod';
export async function forecast(lat: number, lon: number, date: string) {
  const u = new URL('https://api.open-meteo.com/v1/forecast');
  u.search = new URLSearchParams({ latitude: `${lat}`, longitude: `${lon}`, start_date: date, end_date: date,
    hourly: 'precipitation_probability,temperature_2m,wind_speed_10m', timezone: 'auto' }).toString();
  const r = await fetch(u, { signal: AbortSignal.timeout(10_000) });
  if (!r.ok) throw new Error(`open-meteo ${r.status}`);
  const h = (await r.json()).hourly;
  return h.time.map((t: string, i: number) => ({ t: t.slice(11, 16), rain: h.precipitation_probability[i],
    temp: h.temperature_2m[i], wind: h.wind_speed_10m[i] })).filter((x: any) => x.t >= '06:00' && x.t <= '18:00');
}
export const weatherTool = createTool({
  id: 'weather', description: 'Hourly rain %, °C and wind km/h for a lat/lon on YYYY-MM-DD (06–18 local)',
  inputSchema: z.object({ lat: z.number(), lon: z.number(), date: z.string() }),
  execute: async ({ lat, lon, date }) => ({ hours: await forecast(lat, lon, date) }),
});
```

```ts
// places.ts — real named spots near home from OpenStreetMap (Overpass)
export async function places(lat: number, lon: number, radiusM = 25_000) {
  const a = `(around:${radiusM},${lat},${lon})`;
  const q = `[out:json][timeout:25];(nwr${a}[leisure~"^(park|nature_reserve)$"][name];` +
            `nwr${a}[route=hiking][name];nwr${a}[tourism=viewpoint][name];);out center tags 40;`;
  const r = await fetch('https://overpass-api.de/api/interpreter',
    { method: 'POST', body: new URLSearchParams({ data: q }), signal: AbortSignal.timeout(30_000) });
  if (!r.ok) throw new Error(`overpass ${r.status}`);
  return (await r.json()).elements.map((e: any) => ({ name: e.tags.name, kind: e.tags.leisure ?? e.tags.route ?? e.tags.tourism,
    lat: e.lat ?? e.center?.lat, lon: e.lon ?? e.center?.lon, toilets: e.tags.toilets, wheelchair: e.tags.wheelchair }));
}
export const placesTool = createTool({
  id: 'places', description: 'Named parks, hiking routes and viewpoints within radiusM of a lat/lon',
  inputSchema: z.object({ lat: z.number(), lon: z.number(), radiusM: z.number().max(40_000).default(25_000) }),
  execute: async ({ lat, lon, radiusM }) => ({ spots: (await places(lat, lon, radiusM)).slice(0, 25) }),
});
```

### (e) Memory: `src/mastra/memory.ts`

```ts
import { Memory } from '@mastra/memory';
import { MongoDBStore, MongoDBVector } from '@mastra/mongodb';
import { ModelRouterEmbeddingModel } from '@mastra/core/llm';
const uri = process.env.MONGODB_URI!, dbName = process.env.MONGODB_DB ?? 'quorum';
export const memory = new Memory({
  storage: new MongoDBStore({ id: 'quorum-store', uri, dbName }),
  vector: new MongoDBVector({ id: 'quorum-vector', uri, dbName }),        // Atlas Vector Search
  embedder: new ModelRouterEmbeddingModel('google/gemini-embedding-001'), // 768-d, same key
  options: {
    lastMessages: 20,
    semanticRecall: { topK: 4, messageRange: 1, scope: 'resource' },      // all threads of this chat
  },
});
```

`resource = chat:<chatId>`. Threads: `roster:<chatId>` (every `/me`), `plan:<chatId>:<date>` (drafting), `recap:<chatId>:<date>`. With `scope: 'resource'`, drafting next week's plan can recall a `/me` from weeks ago and last Sunday's recap. That is the Atlas evidence. Mastra creates the vector index itself, which uses 1 of M0's 3 indexes. Don't create others.

### (f) Agent: `src/mastra/agents/quorum.ts`

```ts
import { Agent } from '@mastra/core/agent';
import { quorumModel } from '../../shared/model';
import { memory } from '../memory';
import { weatherTool, placesTool } from '../tools';
import { liveCheckTool } from '../tools/liveCheck';
const instructions = `You plan ONE small real-world outing for a friend group.
- Every option must respect EVERY roster constraint. List in shapedBy which constraints changed it.
- Call weather for the date and places near home before proposing. Use ONLY place names returned by tools.
- 2–3 options, each 1–4 hours, within 30 km, starting 06:30–10:00 local. Plain words, no hype.
- If someone's constraint can't be met by any option, say so in shapedBy instead of hiding it.`;
