### (h) Optional live check (SerpApi, cached): `src/mastra/tools/liveCheck.ts`

```ts
import { createHash } from 'node:crypto';
export const liveCheckTool = createTool({
  id: 'liveCheck', description: 'Search the web for closures/events at a named place this week (cached 12 h)',
  inputSchema: z.object({ query: z.string().max(120) }),
  execute: async ({ query }) => {
    const col = (await db()).collection<{ _id: string; results: unknown[] }>('serp_cache');
    const _id = createHash('sha1').update(query.toLowerCase()).digest('hex');
    const hit = await col.findOne({ _id }); if (hit) return { cached: true, results: hit.results };
    const u = new URL('https://serpapi.com/search.json');
    u.search = new URLSearchParams({ engine: 'google', q: query, num: '5', api_key: process.env.SERPAPI_KEY! }).toString();
    const j = await (await fetch(u, { signal: AbortSignal.timeout(15_000) })).json();
    const results = (j.organic_results ?? []).slice(0, 5).map((o: any) => ({ title: o.title, snippet: o.snippet, date: o.date }));
    await col.updateOne({ _id }, { $set: { query, results, fetchedAt: new Date() } }, { upsert: true });
    return { cached: false, results };
  },
});
```

Create the TTL index once: `db.serp_cache.createIndex({ fetchedAt: 1 }, { expireAfterSeconds: 43200 })`. This is a normal index, not a search index, so it doesn't count against the 3. Expose `liveCheck` only to the real group, never on `/try`, so judges can't drain 250 searches.

