```ts
import * as wf from '@temporalio/workflow';
import type * as acts from './activities';
import type { Option } from '../shared/schema';
// Calls that cross the internet to Render/Gemma: fail fast (25 s fetch timeout inside), retry patiently.
const remote = wf.proxyActivities<typeof acts>({ startToCloseTimeout: '60 seconds',
  retry: { initialInterval: '5 seconds', backoffCoefficient: 2, maximumInterval: '2 minutes',
           maximumAttempts: 12, nonRetryableErrorTypes: ['BadRequest'] } });
const chat = wf.proxyActivities<typeof acts>({ startToCloseTimeout: '20 seconds', retry: { maximumAttempts: 6 } });
export const vote  = wf.defineSignal<[{ userId: string; name: string; optionIds: number[] }]>('vote');
export const recap = wf.defineSignal<[{ userId: string; name: string; line: string; photoFileId?: string }]>('recap');
export const phaseQuery = wf.defineQuery<string>('phase');
export interface PlanInput { planId: string; chatId: string; date: string; quorum: number;
  pollCloseAt: number; weatherCheckAt: number; reminderAt: number; outingEndAt: number }
const until = (t: number) => Math.max(1_000, t - Date.now());  // workflow Date.now() is deterministic
