`wf.SignalArgs<any>` is a lazy type. Replace it with the recap payload type if your TS version complains. Durations accept both ms numbers and strings like `'6 hours'`.

### (j) Activities, including the Render cold start as a real retried call: `src/temporal/activities.ts`

```ts
import { Context, ApplicationFailure } from '@temporalio/activity';
import { db, roster } from '../shared/db';
import type { PlanInput } from './workflows'; import type { Option } from '../shared/schema';
const HOME = { lat: Number(process.env.HOME_LAT), lon: Number(process.env.HOME_LON) };
async function logEvent(planId: string, type: string, detail: string) {
  await (await db()).collection('plans').updateOne({ _id: planId as any },
    { $push: { events: { at: new Date(), type, detail } } as any }, { upsert: true });
}
async function render(planId: string, path: string, body: unknown) {
  const { attempt, activityType } = Context.current().info; const t0 = Date.now();
  try {
    const r = await fetch(`${process.env.RENDER_URL}${path}`, { method: 'POST', body: JSON.stringify(body),
      headers: { 'content-type': 'application/json', 'x-quorum-secret': process.env.QUORUM_SHARED_SECRET! },
      signal: AbortSignal.timeout(25_000) });                             // fail fast; Temporal retries
    if (r.status === 400 || r.status === 401)
      throw ApplicationFailure.create({ type: 'BadRequest', message: await r.text(), nonRetryable: true });
    if (!r.ok) throw new Error(`render ${r.status}`);                    // 5xx while waking, 429 from Gemma
    await logEvent(planId, activityType, `attempt ${attempt} ok in ${Date.now() - t0} ms`);
    return await r.json();
  } catch (e: any) { await logEvent(planId, activityType, `attempt ${attempt} failed: ${e.name}: ${e.message}`); throw e; }
}
