const TG = `https://api.telegram.org/bot${process.env.TELEGRAM_BOT_TOKEN}`;
async function tg(method: string, body: object) {
  const r = await fetch(`${TG}/${method}`, { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body), signal: AbortSignal.timeout(15_000) });
  const j = await r.json(); if (!j.ok) throw new Error(`${method}: ${j.description}`); return j.result;
}
export async function sendPoll(planId: string, chatId: string, options: Option[]) {
  const m = await tg('sendPoll', { chat_id: chatId, question: 'Which one are we actually doing? (tap all you can make)',
    options: [...options.map((o) => ({ text: o.title })), { text: "Can't make it" }],
    is_anonymous: false, allows_multiple_answers: true });             // non-anonymous → poll_answer updates
  await (await db()).collection<any>('polls').insertOne({ _id: m.poll.id, planId, chatId, messageId: m.message_id });
}
export async function closePoll(planId: string) {
  const poll = await (await db()).collection<any>('polls').findOne({ planId });
  if (poll) await tg('stopPoll', { chat_id: poll.chatId, message_id: poll.messageId }).catch(() => undefined);
}
