```ts
async function onVote(a: any) {
  const poll = await (await db()).collection<any>('polls').findOne({ _id: a.poll_id });
  if (poll) await temporal.workflow.getHandle(poll.planId)
    .signal(vote, { userId: String(a.user.id), name: a.user.first_name, optionIds: a.option_ids }); // [] = retracted
}
async function onMessage(m: any) {
  if (!m) return;
  const chatId = String(m.chat.id), userId = String(m.from.id), name = m.from.first_name;
  const [, cmd, args = ''] = (m.text ?? '').match(/^\/(\w+)(?:@\w+)?\s*(.*)$/s) ?? [];
  const members = (await db()).collection<any>('members'), _id = `${chatId}:${userId}`;
  if (cmd === 'join') { await members.updateOne({ _id }, { $set: { chatId, userId, name, consentAt: new Date() } }, { upsert: true });
    return send(chatId, `${name} joined. I only see commands and replies to me. /forget removes you.`); }
  if (cmd === 'forget') { await members.deleteOne({ _id }); return send(chatId, `Forgotten, ${name}.`); }
  if (cmd === 'me') { await members.updateOne({ _id }, { $push: { constraints: { text: args, addedAt: new Date() } } });
    return rememberRemote(chatId, name, args); }       // POST /quorum/remember (best effort)
  if (cmd === 'plan') return startPlan(chatId, args);
  if (m.reply_to_message?.from?.is_bot) return onRecap(chatId, userId, name, m);
}
