cat > db.ts <<'EOF'
import { MongoClient, type Db } from 'mongodb';
import type { RosterLine } from './schema';

let client: MongoClient | undefined;

// One client per process. M0 allows 500 connections, so keep the pool small.
export async function db(): Promise<Db> {
  if (!process.env.MONGODB_URI) throw new Error('MONGODB_URI is not set');
  client ??= new MongoClient(process.env.MONGODB_URI, { maxPoolSize: 5, serverSelectionTimeoutMS: 10_000 });
  await client.connect(); // no-op if connected
  return client.db(process.env.MONGODB_DB ?? 'quorum');
}

export async function roster(chatId: string): Promise<RosterLine[]> {
  const ms = await (await db()).collection('members').find({ chatId }).toArray();
  return ms.map((m) => ({ name: m.name as string, constraints: (m.constraints ?? []).map((c: any) => c.text) }));
}

export async function logEvent(planId: string, type: string, detail: string) {
  await (await db()).collection<any>('plans').updateOne(
    { _id: planId },
    { $push: { events: { at: new Date(), type, detail } } },
    { upsert: true },
  );
}

// Normal indexes only (no search indexes: M0 allows 3 and Mastra needs one).
export async function ensureIndexes() {
  const d = await db();
  await d.collection('serp_cache').createIndex({ fetchedAt: 1 }, { expireAfterSeconds: 43_200 });
  await d.collection('members').createIndex({ chatId: 1 });
  await d.collection('plans').createIndex({ chatId: 1, status: 1 });
  await d.collection('polls').createIndex({ planId: 1 });
  await d.collection('try_hits').createIndex({ at: 1 }, { expireAfterSeconds: 3_600 });
}
EOF
cat > time.ts <<'EOF'
// Time math lives in the client (bot). The workflow only ever sees absolute ms timestamps.
const OFF = () => process.env.GROUP_UTC_OFFSET ?? '+05:00';

export const at = (date: string, hhmm: string) => Date.parse(`${date}T${hhmm}:00${OFF()}`);
export const dayBefore = (d: string) => new Date(Date.parse(`${d}T12:00:00Z`) - 864e5).toISOString().slice(0, 10);

// Today's date in the group's local time zone (YYYY-MM-DD).
export function localToday(now = Date.now()) {
  const [, sign, h, m] = OFF().match(/^([+-])(\d\d):(\d\d)$/) ?? ['', '+', '00', '00'];
  const offMs = (sign === '-' ? -1 : 1) * (Number(h) * 60 + Number(m)) * 60_000;
  return new Date(now + offMs).toISOString().slice(0, 10);
}

export function fmtLocal(ms: number) {
  const [, sign, h, m] = OFF().match(/^([+-])(\d\d):(\d\d)$/) ?? ['', '+', '00', '00'];
  const offMs = (sign === '-' ? -1 : 1) * (Number(h) * 60 + Number(m)) * 60_000;
  return new Date(ms + offMs).toISOString().slice(0, 16).replace('T', ' ');
}

export interface Schedule { pollCloseAt: number; weatherCheckAt: number; reminderAt: number; outingEndAt: number }

export function realSchedule(date: string): Schedule {
  return {
    pollCloseAt: at(dayBefore(date), process.env.POLL_CLOSE ?? '22:00'),
    weatherCheckAt: at(date, '05:30'),
    reminderAt: at(date, '06:00'),
    outingEndAt: at(date, process.env.OUTING_END ?? '10:30'),
  };
}

// `/plan test`: the same workflow compressed into minutes.
export function testSchedule(now = Date.now()): Schedule {
  const min = 60_000;
  return { pollCloseAt: now + 3 * min, weatherCheckAt: now + 5 * min, reminderAt: now + 6 * min, outingEndAt: now + 8 * min };
}
EOF

